onClick:
{{
  (async () => {
    // 1. Unverzüglich Modal schließen & Input zurücksetzen für sofortiges Feedback
    closeModal('Modal_Programm');
    resetWidget('inp_Bemerkung', true);

    const jetzigerZeitstempel = moment().format('DD.MM.YYYY HH:mm');
    const activeV = String(appsmith.store.activeVentil || "").trim();
    const daten = Bewaesserung_Lesen.data || [];
    const bemerkungText = inp_Bemerkung.text || "";

    // 2. Unfertigen Eintrag suchen
    let existIndex = -1;
    for (let i = 0; i < daten.length; i++) {
      const vRow = String(daten[i].Ventil || "").trim();
      const match = vRow === activeV || (!isNaN(parseFloat(vRow)) && parseFloat(vRow) === parseFloat(activeV));
      const unfertig = String(daten[i].Status || "").trim().toLowerCase() !== "fertig";

      if (match && unfertig) {
        existIndex = i;
        break;
      }
    }

    try {
      // 3. Modus speichern
      storeValue('selectedModus', 'Jetzt');

      // 4. Haupt-Speicheraktion & Status-Update ausführen
      if (existIndex !== -1) {
        await Bewaesserung_Update_Eintrag.run({
          "realRowIndex": existIndex,
          "programm": appsmith.store.selectedProg,
          "modus": 'Jetzt',
          "zeitstempel": jetzigerZeitstempel,
          "bemerkung": bemerkungText
        });
      } else {
        await Bewaesserung_Speichern.run({
          "ventilName": appsmith.store.activeVentil,
          "programm": appsmith.store.selectedProg,
          "modus": 'Jetzt',
          "zeitstempel": jetzigerZeitstempel,
          "bemerkung": bemerkungText,
          // Falls Stammdaten nicht zwingend im Body der Query benötigt werden,
          // diesen Parameter in der Query direkt referenzieren, statt ihn mitzusenden!
          "stammdaten": Stammdaten.data 
        });
      }

      // Parallel ausführen: Status zurücksetzen und Tabellen neu laden
      await Promise.all([
        Stammdaten_Update.run({ "neuerStatus": "" }),
        Bewaesserung_Lesen.run(),
        Stammdaten.run()
      ]);

    } catch (e) {
      showAlert("Fehler beim Speichern: " + e.message, "error");
    }
  })()
}}
